INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27810172-0517-4bf0-a427-500599bc5180', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which IS-IS level supports intra-area routing in Junos OS?', '[{"id": "A", "text": "Level 1", "is_correct": true}, {"id": "B", "text": "Level 2", "is_correct": false}, {"id": "C", "text": "Level 1 and Level 2", "is_correct": false}, {"id": "D", "text": "Level 0", "is_correct": false}]', 'IS-IS Level 1 handles intra-area (within area) routing. Level 2 handles inter-area routing between different areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/is-is/"}', 'IS-IS', 12.0, 'f46bbde1052f3643_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e980e1d-7169-482d-afcb-72d7a4685433', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast network in Junos OS?', '[{"id": "A", "text": "10 seconds", "is_correct": true}, {"id": "B", "text": "30 seconds", "is_correct": false}, {"id": "C", "text": "40 seconds", "is_correct": false}, {"id": "D", "text": "5 seconds", "is_correct": false}]', 'OSPF hello interval defaults to 10 seconds on broadcast and point-to-point networks, and 30 seconds on NBMA networks.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF', 12.0, '6edbee983e047bef_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('305b360e-bc71-41ce-8559-f5e27df4d20a', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which BGP attribute is used for loop prevention within an AS?', '[{"id": "A", "text": "AS_PATH", "is_correct": true}, {"id": "B", "text": "NEXT_HOP", "is_correct": false}, {"id": "C", "text": "LOCAL_PREF", "is_correct": false}, {"id": "D", "text": "MED", "is_correct": false}]', 'AS_PATH is the primary loop prevention mechanism in BGP. When a router sees its own AS in the AS_PATH, it rejects the route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP', 14.0, '71d38573e702f6be_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a742f0ad-0991-4e9e-8a99-fa1695df4dfc', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'Which command displays OSPF neighbor information on Junos?', '[{"id": "A", "text": "show ospf neighbor", "is_correct": true}, {"id": "B", "text": "show ospf interface", "is_correct": false}, {"id": "C", "text": "show ospf database", "is_correct": false}, {"id": "D", "text": "show protocols ospf neighbor", "is_correct": false}]', '''show ospf neighbor'' displays OSPF adjacency states, neighbor IDs, and interface information.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF', 10.0, '09c381ca020e8136_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63429edc-589a-4249-a2d5-73d9232e588b', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In Junos, which policy action is used to reject a route?', '[{"id": "A", "text": "reject", "is_correct": true}, {"id": "B", "text": "deny", "is_correct": false}, {"id": "C", "text": "discard", "is_correct": false}, {"id": "D", "text": "drop", "is_correct": false}]', 'The ''reject'' action in a routing policy term rejects the route. In Junos, ''then reject'' is used in policy-options.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '152e6787990e2098_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab2f9d21-e526-453e-bdc3-b1dbc40ee516', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default preference for OSPF external routes in Junos?', '[{"id": "A", "text": "150", "is_correct": true}, {"id": "B", "text": "10", "is_correct": false}, {"id": "C", "text": "170", "is_correct": false}, {"id": "D", "text": "120", "is_correct": false}]', 'OSPF external routes (Type 5) have a default preference of 150 in Junos. OSPF internal routes have preference 10.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 10.0, 'c8c4212c182f2687_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64d77b83-3b04-4740-ba2d-3ce29e0e4625', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'multiple-choice', 2, 'understand', 'Which two statements about OSPF areas are correct? (Select TWO)', '[{"id": "A", "text": "Area 0 is the backbone area", "is_correct": true}, {"id": "B", "text": "All non-backbone areas must connect to Area 0", "is_correct": true}, {"id": "C", "text": "Stub areas can contain ASBRs", "is_correct": false}, {"id": "D", "text": "NSSA allows external routes with Type 7 LSAs", "is_correct": false}]', 'Area 0 is the backbone; all non-backbone areas must connect to it. Stub areas cannot contain ASBRs. NSSA uses Type 7 LSAs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF', 14.0, '5da063db42381922_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42e49805-076a-4c4c-90f7-b060393c7e76', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What happens when a BGP route has multiple paths with the same LOCAL_PREF?', '[{"id": "A", "text": "The shortest AS_PATH wins", "is_correct": true}, {"id": "B", "text": "The lowest MED wins", "is_correct": false}, {"id": "C", "text": "The oldest route wins", "is_correct": false}, {"id": "D", "text": "EBGP over IBGP", "is_correct": false}]', 'After LOCAL_PREF, BGP compares AS_PATH length (shorter is better). Then it checks origin type, MED, EBGP vs IBGP, and IGP metric.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '0f4c547149bddfc8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b81c3204-3e63-4efc-adaa-5f8ed5fca85d', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command shows BGP routes in the routing table of a Junos device?', '[{"id": "A", "text": "show route protocol bgp", "is_correct": true}, {"id": "B", "text": "show bgp routes", "is_correct": false}, {"id": "C", "text": "show route bgp", "is_correct": false}, {"id": "D", "text": "show protocols bgp routes", "is_correct": false}]', '''show route protocol bgp'' displays BGP routes in the routing table. ''show bgp summary'' shows BGP peering status.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Operations', 8.0, 'a4f1e54f3c4f8d71_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3abd2373-0564-4086-971e-f957807ea0e5', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of the ''load-balance'' per-packet action in Junos?', '[{"id": "A", "text": "Distribute traffic across multiple equal-cost paths", "is_correct": true}, {"id": "B", "text": "Distribute traffic based on source IP", "is_correct": false}, {"id": "C", "text": "Create a static route for load sharing", "is_correct": false}, {"id": "D", "text": "Enable per-flow load balancing", "is_correct": false}]', '''load-balance per-packet'' enables per-packet load balancing across equal-cost multipath (ECMP) routes in the forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '4b02222a16d4b130_gen_v3', true) ON CONFLICT (id) DO NOTHING;
