INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78ab6b43-0a00-44b5-b918-a9bcff260d55', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'multiple-choice', 3, 'understand', 'Which two MPLS applications typically use LDP for label distribution? (Select TWO) (variant 3).', '[{"id": "A", "text": "Layer 3 VPN (RFC 4364)", "is_correct": true}, {"id": "B", "text": "Layer 2 Circuit", "is_correct": true}, {"id": "C", "text": "MPLS-TE", "is_correct": false}, {"id": "D", "text": "RSVP", "is_correct": false}]', 'L3VPN and Layer 2 Circuit both use LDP for transport label distribution. MPLS-TE uses RSVP, and RSVP is a separate protocol (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Applications', 14.0, 'd245662169cb632b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3838457b-f2a0-4521-b187-8a5cf47a91da', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does the ''policy-options'' community ''target:100:1'' specify in Junos (variant 3).', '[{"id": "A", "text": "Route target community for VPN: AS 100, local ID 1", "is_correct": true}, {"id": "B", "text": "BGP community 100:1", "is_correct": false}, {"id": "C", "text": "MSDP mesh group identifier", "is_correct": false}, {"id": "D", "text": "MPLS label range", "is_correct": false}]', 'Target communities follow format ''target:<ASN>:<local-assigned>''. Route targets control VRF import/export policies (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'VPN Policy', 12.0, '4e4db96fdfdd1d48_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8acec2e2-c018-44b3-b98e-3c931250fafe', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a route reflector hierarchy, what is a ''client-to-client reflection'' (variant 3).', '[{"id": "A", "text": "RR reflects routes between its clients by default", "is_correct": true}, {"id": "B", "text": "Clients must peer directly with each other", "is_correct": false}, {"id": "C", "text": "RR only reflects routes from non-clients", "is_correct": false}, {"id": "D", "text": "Client-to-client reflection is disabled by default", "is_correct": false}]', 'By default, a BGP route reflector reflects routes learned from one client to all other clients. This can be disabled with ''no-client-to-client-reflection'' (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 14.0, '362fdcb3d6fc2481_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('304cdd33-8862-4171-b520-1c193c384e91', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'Which command verifies LDP session status in Junos (variant 3).', '[{"id": "A", "text": "show ldp session", "is_correct": true}, {"id": "B", "text": "show mpls ldp session", "is_correct": false}, {"id": "C", "text": "show ldp neighbor", "is_correct": false}, {"id": "D", "text": "show protocols ldp status", "is_correct": false}]', '''show ldp session'' displays LDP session state, neighbor address, and label advertisement mode. ''show ldp neighbor'' shows discovery state (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP Operations', 8.0, '6cb19878b7a33ec8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ab163e41-3afa-4c77-b480-ea7b5113017d', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'What is the default MPLS label range for dynamic labels in Junos?', '[{"id": "A", "text": "16 through 1023", "is_correct": true}, {"id": "B", "text": "0 through 15", "is_correct": false}, {"id": "C", "text": "1024 through 65535", "is_correct": false}, {"id": "D", "text": "1 through 1000", "is_correct": false}]', 'Junos uses label range 0-15 for reserved labels (e.g., 0=IPv4 NULL, 3=implicit NULL). Dynamic LDP/RSVP labels start from 16 through 1023 by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Fundamentals', 14.0, '32286407c224344d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d283efd-0533-4029-b067-3e8c4f50ec32', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', 'Which command shows the MPLS label-switched path (LSP) information in Junos?', '[{"id": "A", "text": "show mpls lsp", "is_correct": true}, {"id": "B", "text": "show mpls path", "is_correct": false}, {"id": "C", "text": "show rsvp lsp", "is_correct": false}, {"id": "D", "text": "show ldp lsp", "is_correct": false}]', '''show mpls lsp'' displays LSP status, path, and statistics. It shows ingress, transit, and egress LSPs.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 14.0, '6e10b3d7d19e99d3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6947e265-5eaf-4020-a240-a1076b5d90b3', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the purpose of the MPLS explicit NULL label (value 0)?', '[{"id": "A", "text": "The egress router pops the label and performs an IP lookup", "is_correct": true}, {"id": "B", "text": "The penultimate hop pops the label", "is_correct": false}, {"id": "C", "text": "It indicates an IPv6 payload", "is_correct": false}, {"id": "D", "text": "It is used for OAM operations", "is_correct": false}]', 'Explicit NULL (label 0) tells the penultimate hop to retain the label. The egress router pops it and does an IP lookup. Used when QoS information is in the MPLS header.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Label Operations', 12.0, 'b504e82e3c55014f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aecad92e-b8ec-4f5a-859b-6f61266c4f6b', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'Which RSVP message is used to tear down an established LSP?', '[{"id": "A", "text": "PathTear", "is_correct": true}, {"id": "B", "text": "ResvTear", "is_correct": false}, {"id": "C", "text": "PathErr", "is_correct": false}, {"id": "D", "text": "ResvErr", "is_correct": false}]', 'PathTear travels from ingress to egress tearing down the LSP. ResvTear travels upstream from egress to ingress.', '{"https://www.juniper.net/documentation/us/en/software/junos/rsvp/"}', 'RSVP-TE', 14.0, 'c603a912294b7770_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1652d792-d756-4eff-a878-7d86f7282d20', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'In the context of MPLS, what is PHP?', '[{"id": "A", "text": "Penultimate Hop Popping - the second-to-last router removes the label", "is_correct": true}, {"id": "B", "text": "Path Hop Protocol - a signaling mechanism", "is_correct": false}, {"id": "C", "text": "Per-Hop Policing - QoS enforcement", "is_correct": false}, {"id": "D", "text": "Provider Hub Point - a central aggregation router", "is_correct": false}]', 'PHP is when the penultimate hop router pops the MPLS label before forwarding the packet to the egress router. This reduces the load on the egress router.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 12.0, 'd642ad095439d56a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7199dae-75d6-438f-9bca-1fcbd39f62dd', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'What is the default MPLS label range for dynamic labels in Junos (variant 2).', '[{"id": "A", "text": "16 through 1023", "is_correct": true}, {"id": "B", "text": "0 through 15", "is_correct": false}, {"id": "C", "text": "1024 through 65535", "is_correct": false}, {"id": "D", "text": "1 through 1000", "is_correct": false}]', 'Junos uses label range 0-15 for reserved labels (e.g., 0=IPv4 NULL, 3=implicit NULL). Dynamic LDP/RSVP labels start from 16 through 1023 by default (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Fundamentals', 14.0, '75ab0f14f8128d50_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('079fe69b-7dc7-48b8-8cc6-e219251f9f27', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', 'Which command shows the MPLS label-switched path (LSP) information in Junos (variant 2).', '[{"id": "A", "text": "show mpls lsp", "is_correct": true}, {"id": "B", "text": "show mpls path", "is_correct": false}, {"id": "C", "text": "show rsvp lsp", "is_correct": false}, {"id": "D", "text": "show ldp lsp", "is_correct": false}]', '''show mpls lsp'' displays LSP status, path, and statistics. It shows ingress, transit, and egress LSPs (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 14.0, '28574955dd9cdfc4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e581b962-1b16-4a38-8d12-16423aa8856b', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the purpose of the MPLS explicit NULL label (value 0) (variant 2).', '[{"id": "A", "text": "The egress router pops the label and performs an IP lookup", "is_correct": true}, {"id": "B", "text": "The penultimate hop pops the label", "is_correct": false}, {"id": "C", "text": "It indicates an IPv6 payload", "is_correct": false}, {"id": "D", "text": "It is used for OAM operations", "is_correct": false}]', 'Explicit NULL (label 0) tells the penultimate hop to retain the label. The egress router pops it and does an IP lookup. Used when QoS information is in the MPLS header (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Label Operations', 12.0, 'd488a8cc9c11e32e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b9c50ad-5e60-46e0-85fb-7a216b3b9dff', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'Which RSVP message is used to tear down an established LSP (variant 2).', '[{"id": "A", "text": "PathTear", "is_correct": true}, {"id": "B", "text": "ResvTear", "is_correct": false}, {"id": "C", "text": "PathErr", "is_correct": false}, {"id": "D", "text": "ResvErr", "is_correct": false}]', 'PathTear travels from ingress to egress tearing down the LSP. ResvTear travels upstream from egress to ingress (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/rsvp/"}', 'RSVP-TE', 14.0, 'e6c8084a2b625fdb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca23a0e6-2c96-4ae5-8631-47a7b809ca37', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'In the context of MPLS, what is PHP (variant 2).', '[{"id": "A", "text": "Penultimate Hop Popping - the second-to-last router removes the label", "is_correct": true}, {"id": "B", "text": "Path Hop Protocol - a signaling mechanism", "is_correct": false}, {"id": "C", "text": "Per-Hop Policing - QoS enforcement", "is_correct": false}, {"id": "D", "text": "Provider Hub Point - a central aggregation router", "is_correct": false}]', 'PHP is when the penultimate hop router pops the MPLS label before forwarding the packet to the egress router. This reduces the load on the egress router (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 12.0, '7334e151c7b57fba_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1cd013f5-4270-4b88-984d-0923346bc027', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'What is the default MPLS label range for dynamic labels in Junos (variant 3).', '[{"id": "A", "text": "16 through 1023", "is_correct": true}, {"id": "B", "text": "0 through 15", "is_correct": false}, {"id": "C", "text": "1024 through 65535", "is_correct": false}, {"id": "D", "text": "1 through 1000", "is_correct": false}]', 'Junos uses label range 0-15 for reserved labels (e.g., 0=IPv4 NULL, 3=implicit NULL). Dynamic LDP/RSVP labels start from 16 through 1023 by default (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Fundamentals', 14.0, 'bd41de7bc911116c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
