INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3725680-64db-4a5f-b120-0c080a0920c0', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'In Junos, which statement about route-target (RT) communities in Layer 3 VPNs is correct?', '[{"id": "A", "text": "RT controls both import and export of VPN routes", "is_correct": true}, {"id": "B", "text": "RT is only used for export policy", "is_correct": false}, {"id": "C", "text": "RT must match the RD value", "is_correct": false}, {"id": "D", "text": "RT is optional in Junos VPN configurations", "is_correct": false}]', 'Route targets control both import and export of VPN routes. Each VRF has vrf-import and vrf-export policies typically matching RT communities.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'L3VPN', 14.0, 'eb5a78953e67537e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dbacc4d0-6ea7-4e0b-b4eb-f35fedf1d64a', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'Which BGP address family is used to carry MPLS-labeled VPN-IPv4 routes?', '[{"id": "A", "text": "inet-vpn-unicast", "is_correct": true}, {"id": "B", "text": "inet-unicast", "is_correct": false}, {"id": "C", "text": "inet-labeled-unicast", "is_correct": false}, {"id": "D", "text": "vpn-ipv4", "is_correct": false}]', 'The ''inet-vpn-unicast'' address family carries VPN-IPv4 routes with MPLS labels in BGP. It is configured under ''family inet-vpn unicast''.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'MP-BGP', 14.0, 'ac01f83fe94a7235_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28aaf980-8324-42eb-8ac9-b84886029e05', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is a Layer 2 Circuit in Junos?', '[{"id": "A", "text": "A point-to-point L2 connection over an MPLS network", "is_correct": true}, {"id": "B", "text": "A multipoint L2 VPN", "is_correct": false}, {"id": "C", "text": "An Ethernet bridge group", "is_correct": false}, {"id": "D", "text": "A virtual switch instance", "is_correct": false}]', 'Layer 2 Circuit provides a point-to-point connection between two customer sites over an MPLS network. It uses LDP for label signaling.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'L2VPN', 14.0, 'e122a8bd9f63cf8c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('428320c1-8dd2-4083-b1da-38808daa8a56', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000002', 'multiple-choice', 3, 'understand', 'Which two conditions are required for an LDP session to establish between two Junos routers? (Select TWO)', '[{"id": "A", "text": "Directly connected interfaces with an IGP route to the loopback", "is_correct": true}, {"id": "B", "text": "BGP peering between loopbacks", "is_correct": false}, {"id": "C", "text": "LDP enabled on the interfaces", "is_correct": true}, {"id": "D", "text": "MPLS-TE enabled on the core", "is_correct": false}]', 'LDP requires directly connected interfaces with IGP reachability between loopbacks, and LDP must be enabled on those interfaces.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'LDP', 14.0, '5bb70cfc802d0dd1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f09afc13-15c5-45f2-ad5f-bbd73a8a984f', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'In VPLS, what is the purpose of the ''site-id'' configured under a routing instance?', '[{"id": "A", "text": "Identifies the local site for loop prevention and MAC learning", "is_correct": true}, {"id": "B", "text": "Defines the VPLS encapsulation type", "is_correct": false}, {"id": "C", "text": "Sets the MTU for the VPLS instance", "is_correct": false}, {"id": "D", "text": "Maps the VPLS to a specific BGP session", "is_correct": false}]', 'The site-id uniquely identifies a VPLS site within the VPLS domain. It is used for split-horizon forwarding and MAC address management.', '{"https://www.juniper.net/documentation/us/en/software/junos/vpls/"}', 'VPLS', 14.0, '71dc3f21cc6e3759_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e28d03f-6fe0-4ebe-b64f-5ffa7394bce9', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'Which command displays the content of the LIB (Label Information Base) in Junos?', '[{"id": "A", "text": "show route table mpls.0", "is_correct": true}, {"id": "B", "text": "show mpls label", "is_correct": false}, {"id": "C", "text": "show ldp database", "is_correct": false}, {"id": "D", "text": "show rsvp session", "is_correct": false}]', 'The LIB is stored in ''mpls.0'' routing table. ''show route table mpls.0'' displays all MPLS labels and their next hops.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 12.0, '7af8077362d43383_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03f75e71-c09d-47f8-afe3-949b259c3e90', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the default BGP MED value for routes redistributed into BGP on Junos?', '[{"id": "A", "text": "0", "is_correct": false}, {"id": "B", "text": "100", "is_correct": false}, {"id": "C", "text": "The IGP metric of the route", "is_correct": true}, {"id": "D", "text": "No MED is set by default", "is_correct": false}]', 'By default, Junos sets the MED to the IGP metric value when redistributing routes into BGP. This is Junos-specific behavior.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP', 12.0, '766b6f82bada698c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce6aab8e-ec5b-4f74-8283-6a9c912e8487', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'Which statement about VRF route leaking in Junos is correct?', '[{"id": "A", "text": "Route leaking allows redistribution between VRFs using logical tunnel interfaces", "is_correct": true}, {"id": "B", "text": "Route leaking is automatic between all VRFs", "is_correct": false}, {"id": "C", "text": "Route leaking only works with OSPF", "is_correct": false}, {"id": "D", "text": "VRF route leaking is not supported in MX series", "is_correct": false}]', 'Route leaking between VRFs in Junos uses logical tunnel (lt) interfaces with RIB groups, auto-export, or BGP between VRF routing instances.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'VRF Advanced', 14.0, '92d3e26d65192912_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6befc095-f46b-45cc-8e23-9c10b635cc4c', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the purpose of the ''vrf-table-label'' configuration in Junos?', '[{"id": "A", "text": "Allocate MPLS labels for each VRF route to enable label-switched inter-VRF forwarding", "is_correct": true}, {"id": "B", "text": "Enable BGP on the VRF table", "is_correct": false}, {"id": "C", "text": "Configure the VRF routing table size", "is_correct": false}, {"id": "D", "text": "Enable VRF route summarization", "is_correct": false}]', '''vrf-table-label'' allocates a unique MPLS label for each route in a VRF table, enabling MPLS forwarding between VRFs without an lt-interface.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'MPLS L3VPN', 14.0, '17bebac806f7d915_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ac67de4-ef5f-4cf3-b8ed-d07b82c92f6c', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'remember', 'Which command shows BGP VPNv4 routes in Junos?', '[{"id": "A", "text": "show route protocol bgp table bgp.l3vpn.0", "is_correct": true}, {"id": "B", "text": "show bgp vpnv4 unicast", "is_correct": false}, {"id": "C", "text": "show route table inet.0 protocol bgp", "is_correct": false}, {"id": "D", "text": "show ldp route", "is_correct": false}]', 'VPNv4 routes are stored in bgp.l3vpn.0 table. ''show route table bgp.l3vpn.0'' displays all VPNv4 routes received from BGP peers.', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'MP-BGP Operations', 12.0, '3be7e064480e0b64_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3c2f2e5-6332-4880-989d-5506b236bc06', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'In Junos, which statement about route-target (RT) communities in Layer 3 VPNs is correct (variant 2).', '[{"id": "A", "text": "RT controls both import and export of VPN routes", "is_correct": true}, {"id": "B", "text": "RT is only used for export policy", "is_correct": false}, {"id": "C", "text": "RT must match the RD value", "is_correct": false}, {"id": "D", "text": "RT is optional in Junos VPN configurations", "is_correct": false}]', 'Route targets control both import and export of VPN routes. Each VRF has vrf-import and vrf-export policies typically matching RT communities (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'L3VPN', 14.0, 'fa60c940f4b2fad8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddfe5175-4b52-49d1-a77d-b05b39730907', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'Which BGP address family is used to carry MPLS-labeled VPN-IPv4 routes (variant 2).', '[{"id": "A", "text": "inet-vpn-unicast", "is_correct": true}, {"id": "B", "text": "inet-unicast", "is_correct": false}, {"id": "C", "text": "inet-labeled-unicast", "is_correct": false}, {"id": "D", "text": "vpn-ipv4", "is_correct": false}]', 'The ''inet-vpn-unicast'' address family carries VPN-IPv4 routes with MPLS labels in BGP. It is configured under ''family inet-vpn unicast'' (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'MP-BGP', 14.0, 'd520f02140638100_gen_v3', true) ON CONFLICT (id) DO NOTHING;
