INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eaddd7af-67ff-44f5-abf9-61aefa7e5b02', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is a Layer 2 Circuit in Junos (variant 3).', '[{"id": "A", "text": "A point-to-point L2 connection over an MPLS network", "is_correct": true}, {"id": "B", "text": "A multipoint L2 VPN", "is_correct": false}, {"id": "C", "text": "An Ethernet bridge group", "is_correct": false}, {"id": "D", "text": "A virtual switch instance", "is_correct": false}]', 'Layer 2 Circuit provides a point-to-point connection between two customer sites over an MPLS network. It uses LDP for label signaling (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'L2VPN', 14.0, '9466d680ae224746_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31cfee59-8998-4cf2-be2b-3c5fa83dd85c', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000002', 'multiple-choice', 3, 'understand', 'Which two conditions are required for an LDP session to establish between two Junos routers? (Select TWO) (variant 3).', '[{"id": "A", "text": "Directly connected interfaces with an IGP route to the loopback", "is_correct": true}, {"id": "B", "text": "BGP peering between loopbacks", "is_correct": false}, {"id": "C", "text": "LDP enabled on the interfaces", "is_correct": true}, {"id": "D", "text": "MPLS-TE enabled on the core", "is_correct": false}]', 'LDP requires directly connected interfaces with IGP reachability between loopbacks, and LDP must be enabled on those interfaces (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'LDP', 14.0, '3295fa6325cc96bf_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71b16403-6b24-4ee7-9214-0c083ac3c3f9', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'In VPLS, what is the purpose of the ''site-id'' configured under a routing instance (variant 3).', '[{"id": "A", "text": "Identifies the local site for loop prevention and MAC learning", "is_correct": true}, {"id": "B", "text": "Defines the VPLS encapsulation type", "is_correct": false}, {"id": "C", "text": "Sets the MTU for the VPLS instance", "is_correct": false}, {"id": "D", "text": "Maps the VPLS to a specific BGP session", "is_correct": false}]', 'The site-id uniquely identifies a VPLS site within the VPLS domain. It is used for split-horizon forwarding and MAC address management (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/vpls/"}', 'VPLS', 14.0, '185a1017b87ab281_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bae2afa-c91b-49ed-9258-6a54f4958286', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'Which command displays the content of the LIB (Label Information Base) in Junos (variant 3).', '[{"id": "A", "text": "show route table mpls.0", "is_correct": true}, {"id": "B", "text": "show mpls label", "is_correct": false}, {"id": "C", "text": "show ldp database", "is_correct": false}, {"id": "D", "text": "show rsvp session", "is_correct": false}]', 'The LIB is stored in ''mpls.0'' routing table. ''show route table mpls.0'' displays all MPLS labels and their next hops (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 12.0, '689918acffed34f0_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10702d07-cd66-46e6-8375-5f486a2be0b5', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the default BGP MED value for routes redistributed into BGP on Junos (variant 3).', '[{"id": "A", "text": "0", "is_correct": false}, {"id": "B", "text": "100", "is_correct": false}, {"id": "C", "text": "The IGP metric of the route", "is_correct": true}, {"id": "D", "text": "No MED is set by default", "is_correct": false}]', 'By default, Junos sets the MED to the IGP metric value when redistributing routes into BGP. This is Junos-specific behavior (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP', 12.0, 'd156f8c3c658c8df_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1004b5ef-fa19-43c0-96d8-ff5188333642', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'Which statement about VRF route leaking in Junos is correct (variant 3).', '[{"id": "A", "text": "Route leaking allows redistribution between VRFs using logical tunnel interfaces", "is_correct": true}, {"id": "B", "text": "Route leaking is automatic between all VRFs", "is_correct": false}, {"id": "C", "text": "Route leaking only works with OSPF", "is_correct": false}, {"id": "D", "text": "VRF route leaking is not supported in MX series", "is_correct": false}]', 'Route leaking between VRFs in Junos uses logical tunnel (lt) interfaces with RIB groups, auto-export, or BGP between VRF routing instances (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'VRF Advanced', 14.0, 'd6eebc292023fafc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('728bb252-f3dd-41e4-b4a3-ebe939aee161', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the purpose of the ''vrf-table-label'' configuration in Junos (variant 3).', '[{"id": "A", "text": "Allocate MPLS labels for each VRF route to enable label-switched inter-VRF forwarding", "is_correct": true}, {"id": "B", "text": "Enable BGP on the VRF table", "is_correct": false}, {"id": "C", "text": "Configure the VRF routing table size", "is_correct": false}, {"id": "D", "text": "Enable VRF route summarization", "is_correct": false}]', '''vrf-table-label'' allocates a unique MPLS label for each route in a VRF table, enabling MPLS forwarding between VRFs without an lt-interface (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'MPLS L3VPN', 14.0, '725e8c406b706341_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79ec29cd-92e7-4c5e-b909-bf7546643789', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'remember', 'Which command shows BGP VPNv4 routes in Junos (variant 3).', '[{"id": "A", "text": "show route protocol bgp table bgp.l3vpn.0", "is_correct": true}, {"id": "B", "text": "show bgp vpnv4 unicast", "is_correct": false}, {"id": "C", "text": "show route table inet.0 protocol bgp", "is_correct": false}, {"id": "D", "text": "show ldp route", "is_correct": false}]', 'VPNv4 routes are stored in bgp.l3vpn.0 table. ''show route table bgp.l3vpn.0'' displays all VPNv4 routes received from BGP peers (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'MP-BGP Operations', 12.0, '8f1fcaa22c700722_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96d805ea-9224-4fc1-b9d6-07a06e208904', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'In Junos, which statement about route-target (RT) communities in Layer 3 VPNs is correct (variant 4).', '[{"id": "A", "text": "RT controls both import and export of VPN routes", "is_correct": true}, {"id": "B", "text": "RT is only used for export policy", "is_correct": false}, {"id": "C", "text": "RT must match the RD value", "is_correct": false}, {"id": "D", "text": "RT is optional in Junos VPN configurations", "is_correct": false}]', 'Route targets control both import and export of VPN routes. Each VRF has vrf-import and vrf-export policies typically matching RT communities (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'L3VPN', 14.0, '756c9c631c51e786_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12b7e713-aaca-426f-a24b-b3fa1c0df91e', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'Which BGP address family is used to carry MPLS-labeled VPN-IPv4 routes (variant 4).', '[{"id": "A", "text": "inet-vpn-unicast", "is_correct": true}, {"id": "B", "text": "inet-unicast", "is_correct": false}, {"id": "C", "text": "inet-labeled-unicast", "is_correct": false}, {"id": "D", "text": "vpn-ipv4", "is_correct": false}]', 'The ''inet-vpn-unicast'' address family carries VPN-IPv4 routes with MPLS labels in BGP. It is configured under ''family inet-vpn unicast'' (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'MP-BGP', 14.0, '56ca6b54d5bee19b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4af81ec-f670-4f96-8dfa-b94cc7dae8dd', 'b0000000-0000-0000-0000-000000000012', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is a Layer 2 Circuit in Junos (variant 4).', '[{"id": "A", "text": "A point-to-point L2 connection over an MPLS network", "is_correct": true}, {"id": "B", "text": "A multipoint L2 VPN", "is_correct": false}, {"id": "C", "text": "An Ethernet bridge group", "is_correct": false}, {"id": "D", "text": "A virtual switch instance", "is_correct": false}]', 'Layer 2 Circuit provides a point-to-point connection between two customer sites over an MPLS network. It uses LDP for label signaling (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'L2VPN', 14.0, '6c48d33e8bcf3c87_gen_v3', true) ON CONFLICT (id) DO NOTHING;
