INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ca95dc8-ab0a-4236-b4fc-cda9871e2382', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which IPsec mode encrypts the entire IP packet, including the original header (variant 6).', '[{"id": "A", "text": "Tunnel mode", "is_correct": true}, {"id": "B", "text": "Transport mode", "is_correct": false}, {"id": "C", "text": "AH mode", "is_correct": false}, {"id": "D", "text": "ESP mode", "is_correct": false}]', 'Tunnel mode encrypts the entire original IP packet and adds a new IP header. Transport mode only encrypts the payload (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/ipsec/"}', 'IPsec VPN', 14.0, '158a8aeac3c1038d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad1769a2-bc9f-4850-842b-94af56c4f6aa', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is a security zone in SRX (variant 6).', '[{"id": "A", "text": "A logical grouping of interfaces to which security policies are applied", "is_correct": true}, {"id": "B", "text": "A physical security domain on the device", "is_correct": false}, {"id": "C", "text": "A routing instance for security traffic", "is_correct": false}, {"id": "D", "text": "A VLAN segment for guest networks", "is_correct": false}]', 'A security zone is a logical grouping of one or more interfaces. Security policies are applied between zones, controlling traffic from source to destination zones (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/security-zones/"}', 'Security Zones', 14.0, '611612ee5b885677_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b540e446-bba5-490e-acd2-d221c331f331', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'apply', 'Which Junos command creates a NAT source pool (variant 6).', '[{"id": "A", "text": "set security nat source pool POOL1 address 192.168.1.100/32", "is_correct": true}, {"id": "B", "text": "set nat source pool POOL1 range 192.168.1.100", "is_correct": false}, {"id": "C", "text": "set security source-nat pool POOL1 192.168.1.100", "is_correct": false}, {"id": "D", "text": "set services nat pool POOL1 address 192.168.1.100", "is_correct": false}]', 'Source NAT pools are configured under ''security nat source pool <name>''. The pool defines the translated source IP addresses (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/nat/"}', 'NAT', 14.0, '65882b94dd9ec62a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('539c7713-824d-4d11-959e-ae995890eb5c', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'Which Junos feature provides application-aware security policies (variant 7).', '[{"id": "A", "text": "Application Firewall (AppFW)", "is_correct": true}, {"id": "B", "text": "Stateful firewall filtering", "is_correct": false}, {"id": "C", "text": "Simple packet filter", "is_correct": false}, {"id": "D", "text": "MAC-based filtering", "is_correct": false}]', 'AppFW (Application Firewall) identifies applications using Juniper''s Application Signature database, enabling application-aware security policies (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/appfw/"}', 'Security Policies', 14.0, '88714b655279ebb5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d7af6f3-e540-410c-977f-7b1c7cc774ee', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 1, 'remember', 'What is the default action for a Junos security policy if no match is found (variant 7).', '[{"id": "A", "text": "Deny (all traffic not matching a policy is dropped)", "is_correct": true}, {"id": "B", "text": "Permit (all traffic is allowed)", "is_correct": false}, {"id": "C", "text": "Reject with ICMP unreachable", "is_correct": false}, {"id": "D", "text": "Log and permit", "is_correct": false}]', 'Junos uses an implicit deny-all policy. Traffic not matching any security policy is silently dropped. A ''default-permit'' policy can be explicitly configured (Variant 7).', '{"https://www.juniper.net/documentation/us/en/software/junos/security-policies/"}', 'Security Policies', 14.0, '85a46ad3daf95114_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c86fd09c-d59e-41c5-bd5d-35bbf290d978', 'b0000000-0000-0000-0000-000000000023', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', 'What is the purpose of IDP (Intrusion Detection and Prevention) on SRX?', '[{"id": "A", "text": "Inspect traffic for known attack signatures and malicious patterns", "is_correct": true}, {"id": "B", "text": "Filter traffic based on MAC addresses", "is_correct": false}, {"id": "C", "text": "Encrypt traffic between zones", "is_correct": false}, {"id": "D", "text": "Block all traffic from specific countries", "is_correct": false}]', 'IDP uses a signature database to detect and prevent network attacks. It can drop, alert, or ignore traffic based on configured rules.', '{"https://www.juniper.net/documentation/us/en/software/junos/idp/"}', 'IDP', 14.0, 'b2bf63f70ccee62d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b172d29f-55e6-45fe-ac39-8e0ce420d1aa', 'b0000000-0000-0000-0000-000000000023', 'a0000000-0000-0000-0000-000000000003', 'multiple-choice', 3, 'understand', 'Which two methods can be used for user authentication on SRX? (Select TWO)', '[{"id": "A", "text": "Pass-through authentication (web-based)", "is_correct": true}, {"id": "B", "text": "LDAP integration with Active Directory", "is_correct": true}, {"id": "C", "text": "MAC-based authentication", "is_correct": false}, {"id": "D", "text": "Certificate-less TLS authentication", "is_correct": false}]', 'SRX supports pass-through authentication (redirect to captive portal) and firewall authentication via LDAP/AD, RADIUS and local user database.', '{"https://www.juniper.net/documentation/us/en/software/junos/authentication/"}', 'User Authentication', 14.0, 'd001f897cb4128ea_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92e6889c-c4d5-47f6-938a-54bc6166066d', 'b0000000-0000-0000-0000-000000000023', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between ALG and AppFW on SRX?', '[{"id": "A", "text": "ALG handles specific protocols at the application layer (e.g., SIP, FTP); AppFW identifies applications by signature", "is_correct": true}, {"id": "B", "text": "ALG and AppFW are the same feature", "is_correct": false}, {"id": "C", "text": "AppFW handles VoIP protocols; ALG handles web traffic", "is_correct": false}, {"id": "D", "text": "ALG only works in packet mode", "is_correct": false}]', 'ALG (Application Layer Gateway) provides protocol-specific handling for SIP, FTP, H.323 etc. AppFW identifies applications via signatures without protocol-specific parsing.', '{"https://www.juniper.net/documentation/us/en/software/junos/appsec/"}', 'Application Security', 14.0, '2e15c295cd02288c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('502975d5-24e7-448c-8129-00c28c02dca6', 'b0000000-0000-0000-0000-000000000023', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'In Junos, what is a ''scheduler'' in the context of IDP?', '[{"id": "A", "text": "Defines when IDP rules are active (time-based profiles)", "is_correct": true}, {"id": "B", "text": "Manages CPU scheduling for IDP processing", "is_correct": false}, {"id": "C", "text": "Prioritizes IDP inspection queue", "is_correct": false}, {"id": "D", "text": "Schedules IDP signature updates", "is_correct": false}]', 'IDP schedulers define time-based activation of rulebases. For example, strict inspection during business hours and relaxed rules at night.', '{"https://www.juniper.net/documentation/us/en/software/junos/idp/"}', 'IDP Configuration', 14.0, '6be723266f1690a6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61a5bc8d-1632-4fe3-b235-69ffcc8741be', 'b0000000-0000-0000-0000-000000000023', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'remember', 'Which command displays active security policies on an SRX?', '[{"id": "A", "text": "show security policies", "is_correct": true}, {"id": "B", "text": "show configuration security policies", "is_correct": false}, {"id": "C", "text": "show firewall policy", "is_correct": false}, {"id": "D", "text": "show security zones policy", "is_correct": false}]', '''show security policies'' displays active security policies with hit counts and statistics. ''show configuration security policies'' shows the configuration.', '{"https://www.juniper.net/documentation/us/en/software/junos/security-policies/"}', 'Security Operations', 12.0, 'ac53872aaeb23b5c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc712df4-dc2f-4301-ba9a-8d5bca141aa2', 'b0000000-0000-0000-0000-000000000023', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', 'What is the purpose of the SRX ''policer'' configuration?', '[{"id": "A", "text": "Rate-limits traffic based on bandwidth or burst size parameters", "is_correct": true}, {"id": "B", "text": "Drops all traffic from a specific source", "is_correct": false}, {"id": "C", "text": "Enables stateful firewall inspection", "is_correct": false}, {"id": "D", "text": "Configures BGP policies on SRX", "is_correct": false}]', 'Junos policers rate-limit traffic by enforcing bandwidth and burst limits. They can be applied in security policies using ''then policer'' action.', '{"https://www.juniper.net/documentation/us/en/software/junos/security-policies/"}', 'Security Policy Enforcement', 12.0, '6238aa7d01545635_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40e948c2-6bb3-43b8-b2cc-13966acde200', 'b0000000-0000-0000-0000-000000000023', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'Which SRX feature provides SSL/TLS inspection?', '[{"id": "A", "text": "SSL Forward Proxy", "is_correct": true}, {"id": "B", "text": "IPsec VPN", "is_correct": false}, {"id": "C", "text": "Secure Web Gateway", "is_correct": false}, {"id": "D", "text": "Content filtering", "is_correct": false}]', 'SSL Forward Proxy decrypts outbound SSL/TLS traffic, inspects the content, and re-encrypts it before forwarding. Requires a CA certificate installed on clients.', '{"https://www.juniper.net/documentation/us/en/software/junos/ssl-proxy/"}', 'SSL Inspection', 12.0, '113c9afa3236c1ea_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51c48991-037c-4c55-994d-3a9d1d6380fe', 'b0000000-0000-0000-0000-000000000023', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', 'What is the purpose of IDP (Intrusion Detection and Prevention) on SRX (variant 2).', '[{"id": "A", "text": "Inspect traffic for known attack signatures and malicious patterns", "is_correct": true}, {"id": "B", "text": "Filter traffic based on MAC addresses", "is_correct": false}, {"id": "C", "text": "Encrypt traffic between zones", "is_correct": false}, {"id": "D", "text": "Block all traffic from specific countries", "is_correct": false}]', 'IDP uses a signature database to detect and prevent network attacks. It can drop, alert, or ignore traffic based on configured rules (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/idp/"}', 'IDP', 14.0, '9c67c2745293ec83_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e0b29ab-a00e-4f57-99dd-aeb70953a06b', 'b0000000-0000-0000-0000-000000000023', 'a0000000-0000-0000-0000-000000000003', 'multiple-choice', 3, 'understand', 'Which two methods can be used for user authentication on SRX? (Select TWO) (variant 2).', '[{"id": "A", "text": "Pass-through authentication (web-based)", "is_correct": true}, {"id": "B", "text": "LDAP integration with Active Directory", "is_correct": true}, {"id": "C", "text": "MAC-based authentication", "is_correct": false}, {"id": "D", "text": "Certificate-less TLS authentication", "is_correct": false}]', 'SRX supports pass-through authentication (redirect to captive portal) and firewall authentication via LDAP/AD, RADIUS and local user database (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/authentication/"}', 'User Authentication', 14.0, 'd0d1776dda809960_gen_v3', true) ON CONFLICT (id) DO NOTHING;
