INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd4c16df-8f00-443d-a2e6-de78e302d2b6', 'b0000000-0000-0000-0000-000000000023', 'a0000000-0000-0000-0000-000000000003', 'multiple-choice', 3, 'understand', 'Which two methods can be used for user authentication on SRX? (Select TWO) (variant 3).', '[{"id": "A", "text": "Pass-through authentication (web-based)", "is_correct": true}, {"id": "B", "text": "LDAP integration with Active Directory", "is_correct": true}, {"id": "C", "text": "MAC-based authentication", "is_correct": false}, {"id": "D", "text": "Certificate-less TLS authentication", "is_correct": false}]', 'SRX supports pass-through authentication (redirect to captive portal) and firewall authentication via LDAP/AD, RADIUS and local user database (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/authentication/"}', 'User Authentication', 14.0, 'b8a0ffa05c139a13_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cac47edc-9073-47e6-982a-1e854ca72c8f', 'b0000000-0000-0000-0000-000000000023', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between ALG and AppFW on SRX (variant 3).', '[{"id": "A", "text": "ALG handles specific protocols at the application layer (e.g., SIP, FTP); AppFW identifies applications by signature", "is_correct": true}, {"id": "B", "text": "ALG and AppFW are the same feature", "is_correct": false}, {"id": "C", "text": "AppFW handles VoIP protocols; ALG handles web traffic", "is_correct": false}, {"id": "D", "text": "ALG only works in packet mode", "is_correct": false}]', 'ALG (Application Layer Gateway) provides protocol-specific handling for SIP, FTP, H.323 etc. AppFW identifies applications via signatures without protocol-specific parsing (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/appsec/"}', 'Application Security', 14.0, 'f8ac3b4ba8eed206_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0941b47-f2a7-4cbd-9409-ebd98467ea00', 'b0000000-0000-0000-0000-000000000023', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'In Junos, what is a ''scheduler'' in the context of IDP (variant 3).', '[{"id": "A", "text": "Defines when IDP rules are active (time-based profiles)", "is_correct": true}, {"id": "B", "text": "Manages CPU scheduling for IDP processing", "is_correct": false}, {"id": "C", "text": "Prioritizes IDP inspection queue", "is_correct": false}, {"id": "D", "text": "Schedules IDP signature updates", "is_correct": false}]', 'IDP schedulers define time-based activation of rulebases. For example, strict inspection during business hours and relaxed rules at night (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/idp/"}', 'IDP Configuration', 14.0, 'c552490ff3e14864_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e30a5832-3427-4509-8c73-51be4a24fe3d', 'b0000000-0000-0000-0000-000000000023', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'remember', 'Which command displays active security policies on an SRX (variant 3).', '[{"id": "A", "text": "show security policies", "is_correct": true}, {"id": "B", "text": "show configuration security policies", "is_correct": false}, {"id": "C", "text": "show firewall policy", "is_correct": false}, {"id": "D", "text": "show security zones policy", "is_correct": false}]', '''show security policies'' displays active security policies with hit counts and statistics. ''show configuration security policies'' shows the configuration (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/security-policies/"}', 'Security Operations', 12.0, '91c32605a4b56865_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc567420-2cd3-41dc-941d-d7f5a3823687', 'b0000000-0000-0000-0000-000000000023', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', 'What is the purpose of the SRX ''policer'' configuration (variant 3).', '[{"id": "A", "text": "Rate-limits traffic based on bandwidth or burst size parameters", "is_correct": true}, {"id": "B", "text": "Drops all traffic from a specific source", "is_correct": false}, {"id": "C", "text": "Enables stateful firewall inspection", "is_correct": false}, {"id": "D", "text": "Configures BGP policies on SRX", "is_correct": false}]', 'Junos policers rate-limit traffic by enforcing bandwidth and burst limits. They can be applied in security policies using ''then policer'' action (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/security-policies/"}', 'Security Policy Enforcement', 12.0, '582fefa337fafec3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a13c5e44-ce25-4c71-9c7e-2f149780c6c0', 'b0000000-0000-0000-0000-000000000023', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'Which SRX feature provides SSL/TLS inspection (variant 3).', '[{"id": "A", "text": "SSL Forward Proxy", "is_correct": true}, {"id": "B", "text": "IPsec VPN", "is_correct": false}, {"id": "C", "text": "Secure Web Gateway", "is_correct": false}, {"id": "D", "text": "Content filtering", "is_correct": false}]', 'SSL Forward Proxy decrypts outbound SSL/TLS traffic, inspects the content, and re-encrypts it before forwarding. Requires a CA certificate installed on clients (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/ssl-proxy/"}', 'SSL Inspection', 12.0, '577ad67cc949cec2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc5927b1-1e3e-43c5-814f-5d5c0076ad0a', 'b0000000-0000-0000-0000-000000000023', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', 'What is the purpose of IDP (Intrusion Detection and Prevention) on SRX (variant 4).', '[{"id": "A", "text": "Inspect traffic for known attack signatures and malicious patterns", "is_correct": true}, {"id": "B", "text": "Filter traffic based on MAC addresses", "is_correct": false}, {"id": "C", "text": "Encrypt traffic between zones", "is_correct": false}, {"id": "D", "text": "Block all traffic from specific countries", "is_correct": false}]', 'IDP uses a signature database to detect and prevent network attacks. It can drop, alert, or ignore traffic based on configured rules (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/idp/"}', 'IDP', 14.0, 'ea0352d2bfccda4a_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47f98791-1454-4bc5-80e4-c96cc127724a', 'b0000000-0000-0000-0000-000000000023', 'a0000000-0000-0000-0000-000000000003', 'multiple-choice', 3, 'understand', 'Which two methods can be used for user authentication on SRX? (Select TWO) (variant 4).', '[{"id": "A", "text": "Pass-through authentication (web-based)", "is_correct": true}, {"id": "B", "text": "LDAP integration with Active Directory", "is_correct": true}, {"id": "C", "text": "MAC-based authentication", "is_correct": false}, {"id": "D", "text": "Certificate-less TLS authentication", "is_correct": false}]', 'SRX supports pass-through authentication (redirect to captive portal) and firewall authentication via LDAP/AD, RADIUS and local user database (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/authentication/"}', 'User Authentication', 14.0, 'd820f9f6fc5df0d4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
