INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2519486-6d54-40e4-bb9c-555dfc126f92', 'b0000000-0000-0000-0000-000000000023', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between ALG and AppFW on SRX (variant 6).', '[{"id": "A", "text": "ALG handles specific protocols at the application layer (e.g., SIP, FTP); AppFW identifies applications by signature", "is_correct": true}, {"id": "B", "text": "ALG and AppFW are the same feature", "is_correct": false}, {"id": "C", "text": "AppFW handles VoIP protocols; ALG handles web traffic", "is_correct": false}, {"id": "D", "text": "ALG only works in packet mode", "is_correct": false}]', 'ALG (Application Layer Gateway) provides protocol-specific handling for SIP, FTP, H.323 etc. AppFW identifies applications via signatures without protocol-specific parsing (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/appsec/"}', 'Application Security', 14.0, '3f06dd565263d94f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8200eef1-88b2-4ce8-8877-14fa229aee43', 'b0000000-0000-0000-0000-000000000023', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'In Junos, what is a ''scheduler'' in the context of IDP (variant 6).', '[{"id": "A", "text": "Defines when IDP rules are active (time-based profiles)", "is_correct": true}, {"id": "B", "text": "Manages CPU scheduling for IDP processing", "is_correct": false}, {"id": "C", "text": "Prioritizes IDP inspection queue", "is_correct": false}, {"id": "D", "text": "Schedules IDP signature updates", "is_correct": false}]', 'IDP schedulers define time-based activation of rulebases. For example, strict inspection during business hours and relaxed rules at night (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/idp/"}', 'IDP Configuration', 14.0, 'd6139efa9db34c42_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b8d335f-bbe9-4387-8514-5dfbf773e6ef', 'b0000000-0000-0000-0000-000000000023', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'remember', 'Which command displays active security policies on an SRX (variant 6).', '[{"id": "A", "text": "show security policies", "is_correct": true}, {"id": "B", "text": "show configuration security policies", "is_correct": false}, {"id": "C", "text": "show firewall policy", "is_correct": false}, {"id": "D", "text": "show security zones policy", "is_correct": false}]', '''show security policies'' displays active security policies with hit counts and statistics. ''show configuration security policies'' shows the configuration (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/security-policies/"}', 'Security Operations', 12.0, '8a61cf9e6d779be8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('272402bf-ac71-4e29-92bc-238e2ba29a99', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the purpose of SRX chassis clustering?', '[{"id": "A", "text": "Two SRX devices operate as a single cluster for high availability", "is_correct": true}, {"id": "B", "text": "Multiple virtual SRX instances on one chassis", "is_correct": false}, {"id": "C", "text": "Aggregation of physical interfaces", "is_correct": false}, {"id": "D", "text": "Load balancing between two independent firewalls", "is_correct": false}]', 'Chassis clustering enables two physical SRX devices to act as one HA pair with synchronized sessions, configurations, and stateful failover.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster', 14.0, 'a2f47b10c670ac5f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8976fb73-539e-48f8-b7ce-75bf0d2f7c38', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'multiple-choice', 4, 'understand', 'Which two interfaces are required for SRX chassis cluster operation? (Select TWO)', '[{"id": "A", "text": "Control link (fab0/fab1) for IPC", "is_correct": true}, {"id": "B", "text": "Fabric link for session replication", "is_correct": true}, {"id": "C", "text": "Out-of-band management interface", "is_correct": false}, {"id": "D", "text": "A dedicated spanning-tree interface", "is_correct": false}]', 'The control link (fab0) handles control plane IPC. The fabric link (fab1) handles session replication and data plane state synchronization.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster', 14.0, 'ea60acb1b9843db4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('55dceb17-19f8-4231-8963-88921ff7f1dc', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 5, 'understand', 'What is ''logical systems'' on SRX?', '[{"id": "A", "text": "Partitioning a single SRX into multiple virtual firewalls", "is_correct": true}, {"id": "B", "text": "Logical grouping of security policies", "is_correct": false}, {"id": "C", "text": "VLAN segmentation for management traffic", "is_correct": false}, {"id": "D", "text": "A logging subsystem on SRX", "is_correct": false}]', 'Logical Systems (LSYS) partition a single physical SRX into multiple virtual security devices, each with its own routing table, security policies, and administration.', '{"https://www.juniper.net/documentation/us/en/software/junos/logical-systems/"}', 'Logical Systems', 14.0, '748bf804401cfe9f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abcc2e17-7bc0-438c-bb4f-12fc40ce9d36', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the function of ''Security Intelligence'' (SecIntel) on SRX?', '[{"id": "A", "text": "Feeds threat intelligence data from Juniper ATP Cloud to block malicious IPs/URLs", "is_correct": true}, {"id": "B", "text": "A local database of known malware signatures", "is_correct": false}, {"id": "C", "text": "Encrypted traffic analysis using machine learning", "is_correct": false}, {"id": "D", "text": "Geo-IP based blocking", "is_correct": false}]', 'SecIntel feeds real-time threat intelligence from Juniper ATP Cloud. It can block connections to known malicious IPs, URLs, and domains.', '{"https://www.juniper.net/documentation/us/en/software/junos/secintel/"}', 'Advanced Threat Prevention', 14.0, 'fb79bc1cc279e1b6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f1b9f18-6cad-4bc4-b812-65113be3a86b', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', 'Which routing mode is NOT supported on SRX devices?', '[{"id": "A", "text": "Transparent mode (Layer 2)", "is_correct": false}, {"id": "B", "text": "Route mode (Layer 3)", "is_correct": false}, {"id": "C", "text": "NPB (Network Packet Broker) mode", "is_correct": false}, {"id": "D", "text": "All of the above are supported", "is_correct": true}]', 'SRX supports route mode (L3), transparent mode (L2), and NPB mode. Each mode determines how the SRX processes and forwards traffic.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-modes/"}', 'SRX Modes', 12.0, 'fdfc34ae45ac7179_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e344fa53-38a3-4d48-bc50-6b0365460633', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 5, 'understand', 'Which SRX feature enables inter-chassis communication in an active-active cluster?', '[{"id": "A", "text": "Chassis cluster control link for session state synchronization", "is_correct": true}, {"id": "B", "text": "Spanning Tree Protocol", "is_correct": false}, {"id": "C", "text": "VRRP between cluster members", "is_correct": false}, {"id": "D", "text": "LACP between cluster members", "is_correct": false}]', 'Active-active clustering requires the control link for IPC and fabric link for session state synchronization between the two cluster members.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster Advanced', 14.0, 'b64e1786ff2fd8c5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8682ee83-b85f-4f57-bfc0-2fe0aff78367', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the purpose of ''security forwarding-options'' on SRX?', '[{"id": "A", "text": "Configures flow-based processing options including fallback to packet mode", "is_correct": true}, {"id": "B", "text": "Sets routing preferences for security zones", "is_correct": false}, {"id": "C", "text": "Enables NAT on specific interfaces", "is_correct": false}, {"id": "D", "text": "Configures IPsec VPN forwarding", "is_correct": false}]', '''security forwarding-options'' configures the flow-mode behavior, including packet-based fallback for high-throughput traffic that should bypass stateful inspection.', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-forwarding/"}', 'Forwarding Options', 12.0, '3b94929e3d79a3de_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('008363f0-aa81-4346-9b1c-6814ddfc8586', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the purpose of SRX chassis clustering (variant 2).', '[{"id": "A", "text": "Two SRX devices operate as a single cluster for high availability", "is_correct": true}, {"id": "B", "text": "Multiple virtual SRX instances on one chassis", "is_correct": false}, {"id": "C", "text": "Aggregation of physical interfaces", "is_correct": false}, {"id": "D", "text": "Load balancing between two independent firewalls", "is_correct": false}]', 'Chassis clustering enables two physical SRX devices to act as one HA pair with synchronized sessions, configurations, and stateful failover (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/srx-clustering/"}', 'Chassis Cluster', 14.0, '270709f6205ae226_gen_v3', true) ON CONFLICT (id) DO NOTHING;
