INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1c3ccb4-0e53-4a11-a8cb-314c9006992f', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'Which encapsulation technology is commonly used for overlay networks in data center fabrics (variant 9).', '[{"id": "A", "text": "VXLAN", "is_correct": true}, {"id": "B", "text": "GRE", "is_correct": false}, {"id": "C", "text": "IP-IP", "is_correct": false}, {"id": "D", "text": "MPLS", "is_correct": false}]', 'VXLAN (Virtual Extensible LAN) is the most common overlay encapsulation in modern DC fabrics. It uses UDP encapsulation (port 4789) and supports up to 16M segments (Variant 9).', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'Data Center Overlays', 14.0, '51ddb6d15da2ddc7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97930eef-80d5-4394-8c9b-8458a674310e', 'b0000000-0000-0000-0000-000000000025', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'understand', 'In EVPN, what is the purpose of the Route Type 2?', '[{"id": "A", "text": "MAC/IP advertisement route - advertises MAC addresses and optionally IPs", "is_correct": true}, {"id": "B", "text": "Ethernet auto-discovery route", "is_correct": false}, {"id": "C", "text": "Inclusive multicast route", "is_correct": false}, {"id": "D", "text": "Ethernet segment route", "is_correct": false}]', 'EVPN Route Type 2 advertises MAC addresses (and optionally IP addresses) learned on a specific Ethernet segment. It is the core route for MAC learning in EVPN.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '03d6b5f7cc44d205_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74c8cdac-9226-48d7-94e2-4334c753e455', 'b0000000-0000-0000-0000-000000000025', 'a0000000-0000-0000-0000-000000000004', 'multiple-choice', 3, 'understand', 'Which two statements about EVPN Route Type 3 are correct? (Select TWO)', '[{"id": "A", "text": "It provides inclusive multicast Ethernet tagging (IMET)", "is_correct": true}, {"id": "B", "text": "It is used for BUM traffic forwarding", "is_correct": true}, {"id": "C", "text": "It advertises MAC mobility events", "is_correct": false}, {"id": "D", "text": "It replaces VXLAN for multicast", "is_correct": false}]', 'Route Type 3 (IMET) provides multicast tunnel information for BUM traffic. EVPN uses ingress replication or PIM for BUM forwarding.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '943f81c2527dcf39_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54d6781e-07fd-475f-aed4-d7a450636122', 'b0000000-0000-0000-0000-000000000025', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 4, 'understand', 'What is Ethernet Segment Identifier (ESI) in EVPN?', '[{"id": "A", "text": "Identifies a multi-homed site (CE connected to multiple PEs)", "is_correct": true}, {"id": "B", "text": "A MAC address for the segment", "is_correct": false}, {"id": "C", "text": "A VXLAN VNI identifier", "is_correct": false}, {"id": "D", "text": "A BGP community for EVPN routes", "is_correct": false}]', 'ESI is a 10-byte identifier for an Ethernet segment. When a CE is multi-homed to multiple PEs, they share the same ESI for the segment.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Multi-homing', 14.0, '08df52ffa467949f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2f50996-6abe-4946-8775-c6a368333086', 'b0000000-0000-0000-0000-000000000025', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 4, 'understand', 'How does EVPN handle MAC mobility (a MAC moving from one PE to another)?', '[{"id": "A", "text": "Using the MAC Mobility extended community with a sequence number", "is_correct": true}, {"id": "B", "text": "By flapping the ESI", "is_correct": false}, {"id": "C", "text": "By withdrawing the old MAC route", "is_correct": false}, {"id": "D", "text": "MAC mobility is not supported in EVPN", "is_correct": false}]', 'MAC Mobility is signaled via an extended community with a sequence number. The PE with the higher sequence wins. Duplicate MAC detection can also be configured.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN MAC Mobility', 14.0, 'cdac1cd9a6426547_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c1c05275-9e91-4329-9007-4927c1a8e432', 'b0000000-0000-0000-0000-000000000025', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 4, 'understand', 'What is the function of EVPN Route Type 1 (Ethernet Auto-Discovery)?', '[{"id": "A", "text": "Advertises per-ESI and per-EVI information for multi-homing and aliasing", "is_correct": true}, {"id": "B", "text": "Advertises MAC addresses", "is_correct": false}, {"id": "C", "text": "Performs DF election", "is_correct": false}, {"id": "D", "text": "Carries IP prefix routes", "is_correct": false}]', 'Route Type 1 (AD) advertises Ethernet segment and EVI information. It enables mass withdrawal, aliasing, and backup path for multi-homed segments.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '3ae19e56cbd57f68_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd65c35e-057a-4862-8572-68c9324dfa80', 'b0000000-0000-0000-0000-000000000025', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'understand', 'In EVPN-VXLAN, what is an anycast gateway?', '[{"id": "A", "text": "A shared IP and MAC address configured on all leaf switches for default gateway", "is_correct": true}, {"id": "B", "text": "A single centralized gateway router", "is_correct": false}, {"id": "C", "text": "A VRRP-based gateway", "is_correct": false}, {"id": "D", "text": "A gateway that only forwards BUM traffic", "is_correct": false}]', 'Anycast gateway enables active-active default gateway with the same IP/MAC on all leaf switches. Hosts see the same gateway regardless of which leaf they connect to.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Gateway', 14.0, '1f5b32d6499f2e48_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4190229e-7e6a-46fa-9b1a-8e87930fb297', 'b0000000-0000-0000-0000-000000000025', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'understand', 'In EVPN, what is the purpose of the Route Type 2 (variant 2).', '[{"id": "A", "text": "MAC/IP advertisement route - advertises MAC addresses and optionally IPs", "is_correct": true}, {"id": "B", "text": "Ethernet auto-discovery route", "is_correct": false}, {"id": "C", "text": "Inclusive multicast route", "is_correct": false}, {"id": "D", "text": "Ethernet segment route", "is_correct": false}]', 'EVPN Route Type 2 advertises MAC addresses (and optionally IP addresses) learned on a specific Ethernet segment. It is the core route for MAC learning in EVPN (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '54894cd91ee8a349_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d5e8470-ddff-4c61-86ae-648d2f4a58e0', 'b0000000-0000-0000-0000-000000000025', 'a0000000-0000-0000-0000-000000000004', 'multiple-choice', 3, 'understand', 'Which two statements about EVPN Route Type 3 are correct? (Select TWO) (variant 2).', '[{"id": "A", "text": "It provides inclusive multicast Ethernet tagging (IMET)", "is_correct": true}, {"id": "B", "text": "It is used for BUM traffic forwarding", "is_correct": true}, {"id": "C", "text": "It advertises MAC mobility events", "is_correct": false}, {"id": "D", "text": "It replaces VXLAN for multicast", "is_correct": false}]', 'Route Type 3 (IMET) provides multicast tunnel information for BUM traffic. EVPN uses ingress replication or PIM for BUM forwarding (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'dc1535353229cde3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0450d2dd-eea4-4088-82ce-1c764fadcef3', 'b0000000-0000-0000-0000-000000000025', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 4, 'understand', 'What is Ethernet Segment Identifier (ESI) in EVPN (variant 2).', '[{"id": "A", "text": "Identifies a multi-homed site (CE connected to multiple PEs)", "is_correct": true}, {"id": "B", "text": "A MAC address for the segment", "is_correct": false}, {"id": "C", "text": "A VXLAN VNI identifier", "is_correct": false}, {"id": "D", "text": "A BGP community for EVPN routes", "is_correct": false}]', 'ESI is a 10-byte identifier for an Ethernet segment. When a CE is multi-homed to multiple PEs, they share the same ESI for the segment (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Multi-homing', 14.0, 'baffa74a3d4dc6d2_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3151e976-45f0-4459-9b0b-b03bdfc5f293', 'b0000000-0000-0000-0000-000000000025', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 4, 'understand', 'How does EVPN handle MAC mobility (a MAC moving from one PE to another) (variant 2).', '[{"id": "A", "text": "Using the MAC Mobility extended community with a sequence number", "is_correct": true}, {"id": "B", "text": "By flapping the ESI", "is_correct": false}, {"id": "C", "text": "By withdrawing the old MAC route", "is_correct": false}, {"id": "D", "text": "MAC mobility is not supported in EVPN", "is_correct": false}]', 'MAC Mobility is signaled via an extended community with a sequence number. The PE with the higher sequence wins. Duplicate MAC detection can also be configured (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN MAC Mobility', 14.0, '091eea48343fdd40_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('045ad702-5b8d-4250-94b4-8bbffe4df5c1', 'b0000000-0000-0000-0000-000000000025', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 4, 'understand', 'What is the function of EVPN Route Type 1 (Ethernet Auto-Discovery) (variant 2).', '[{"id": "A", "text": "Advertises per-ESI and per-EVI information for multi-homing and aliasing", "is_correct": true}, {"id": "B", "text": "Advertises MAC addresses", "is_correct": false}, {"id": "C", "text": "Performs DF election", "is_correct": false}, {"id": "D", "text": "Carries IP prefix routes", "is_correct": false}]', 'Route Type 1 (AD) advertises Ethernet segment and EVI information. It enables mass withdrawal, aliasing, and backup path for multi-homed segments (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'acbf69ce612834bd_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('600965e2-e747-4d08-a5eb-948cf77decb3', 'b0000000-0000-0000-0000-000000000025', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'understand', 'In EVPN-VXLAN, what is an anycast gateway (variant 2).', '[{"id": "A", "text": "A shared IP and MAC address configured on all leaf switches for default gateway", "is_correct": true}, {"id": "B", "text": "A single centralized gateway router", "is_correct": false}, {"id": "C", "text": "A VRRP-based gateway", "is_correct": false}, {"id": "D", "text": "A gateway that only forwards BUM traffic", "is_correct": false}]', 'Anycast gateway enables active-active default gateway with the same IP/MAC on all leaf switches. Hosts see the same gateway regardless of which leaf they connect to (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Gateway', 14.0, '0c853edf6e0f12d8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fd6c808-8aed-4505-b5b2-4d4b289999d0', 'b0000000-0000-0000-0000-000000000025', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'understand', 'In EVPN, what is the purpose of the Route Type 2 (variant 3).', '[{"id": "A", "text": "MAC/IP advertisement route - advertises MAC addresses and optionally IPs", "is_correct": true}, {"id": "B", "text": "Ethernet auto-discovery route", "is_correct": false}, {"id": "C", "text": "Inclusive multicast route", "is_correct": false}, {"id": "D", "text": "Ethernet segment route", "is_correct": false}]', 'EVPN Route Type 2 advertises MAC addresses (and optionally IP addresses) learned on a specific Ethernet segment. It is the core route for MAC learning in EVPN (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '99499a97163a470e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
