INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2970a64-8907-4715-b31f-ed270b9f4c18', 'b0000000-0000-0000-0000-000000000025', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'understand', 'In EVPN-VXLAN, what is an anycast gateway (variant 5).', '[{"id": "A", "text": "A shared IP and MAC address configured on all leaf switches for default gateway", "is_correct": true}, {"id": "B", "text": "A single centralized gateway router", "is_correct": false}, {"id": "C", "text": "A VRRP-based gateway", "is_correct": false}, {"id": "D", "text": "A gateway that only forwards BUM traffic", "is_correct": false}]', 'Anycast gateway enables active-active default gateway with the same IP/MAC on all leaf switches. Hosts see the same gateway regardless of which leaf they connect to (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN Gateway', 14.0, 'f4bf804ea4e3006c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('332e6adf-e743-475a-8e02-501f7e525def', 'b0000000-0000-0000-0000-000000000025', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'understand', 'In EVPN, what is the purpose of the Route Type 2 (variant 6).', '[{"id": "A", "text": "MAC/IP advertisement route - advertises MAC addresses and optionally IPs", "is_correct": true}, {"id": "B", "text": "Ethernet auto-discovery route", "is_correct": false}, {"id": "C", "text": "Inclusive multicast route", "is_correct": false}, {"id": "D", "text": "Ethernet segment route", "is_correct": false}]', 'EVPN Route Type 2 advertises MAC addresses (and optionally IP addresses) learned on a specific Ethernet segment. It is the core route for MAC learning in EVPN (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, '2cfcc262de378473_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a7acc05e-151b-4a04-9ec7-e59783b7b05d', 'b0000000-0000-0000-0000-000000000025', 'a0000000-0000-0000-0000-000000000004', 'multiple-choice', 3, 'understand', 'Which two statements about EVPN Route Type 3 are correct? (Select TWO) (variant 6).', '[{"id": "A", "text": "It provides inclusive multicast Ethernet tagging (IMET)", "is_correct": true}, {"id": "B", "text": "It is used for BUM traffic forwarding", "is_correct": true}, {"id": "C", "text": "It advertises MAC mobility events", "is_correct": false}, {"id": "D", "text": "It replaces VXLAN for multicast", "is_correct": false}]', 'Route Type 3 (IMET) provides multicast tunnel information for BUM traffic. EVPN uses ingress replication or PIM for BUM forwarding (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'e05ec50df9f010bc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c605dce6-2064-4b75-ac07-d71750996c2d', 'b0000000-0000-0000-0000-000000000025', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 4, 'understand', 'What is Ethernet Segment Identifier (ESI) in EVPN (variant 6).', '[{"id": "A", "text": "Identifies a multi-homed site (CE connected to multiple PEs)", "is_correct": true}, {"id": "B", "text": "A MAC address for the segment", "is_correct": false}, {"id": "C", "text": "A VXLAN VNI identifier", "is_correct": false}, {"id": "D", "text": "A BGP community for EVPN routes", "is_correct": false}]', 'ESI is a 10-byte identifier for an Ethernet segment. When a CE is multi-homed to multiple PEs, they share the same ESI for the segment (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Multi-homing', 14.0, '7941cee0348fc7cc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('15e6e5e5-779e-4c8f-a8b5-da63be939c6d', 'b0000000-0000-0000-0000-000000000025', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 4, 'understand', 'How does EVPN handle MAC mobility (a MAC moving from one PE to another) (variant 6).', '[{"id": "A", "text": "Using the MAC Mobility extended community with a sequence number", "is_correct": true}, {"id": "B", "text": "By flapping the ESI", "is_correct": false}, {"id": "C", "text": "By withdrawing the old MAC route", "is_correct": false}, {"id": "D", "text": "MAC mobility is not supported in EVPN", "is_correct": false}]', 'MAC Mobility is signaled via an extended community with a sequence number. The PE with the higher sequence wins. Duplicate MAC detection can also be configured (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN MAC Mobility', 14.0, '3eeaa30613e45e4d_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5401b93b-8158-4fe8-99e1-a200ba30ec31', 'b0000000-0000-0000-0000-000000000025', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 4, 'understand', 'What is the function of EVPN Route Type 1 (Ethernet Auto-Discovery) (variant 6).', '[{"id": "A", "text": "Advertises per-ESI and per-EVI information for multi-homing and aliasing", "is_correct": true}, {"id": "B", "text": "Advertises MAC addresses", "is_correct": false}, {"id": "C", "text": "Performs DF election", "is_correct": false}, {"id": "D", "text": "Carries IP prefix routes", "is_correct": false}]', 'Route Type 1 (AD) advertises Ethernet segment and EVI information. It enables mass withdrawal, aliasing, and backup path for multi-homed segments (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn/"}', 'EVPN Route Types', 14.0, 'dc63d4d28489d5bc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
