INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7db6c65c-4a26-4ad1-86b7-93255976a8f5', 'b0000000-0000-0000-0000-000000000027', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'Which Ansible module is used to apply a Junos configuration from a file?', '[{"id": "A", "text": "junos_config", "is_correct": true}, {"id": "B", "text": "junos_install_config", "is_correct": false}, {"id": "C", "text": "netconf_config", "is_correct": false}, {"id": "D", "text": "junos_template", "is_correct": false}]', 'The ''junos_config'' module manages Junos configuration by loading, merging, or replacing configuration from a file or inline.', '{"https://www.juniper.net/documentation/us/en/software/junos/ansible/"}', 'Ansible Automation', 14.0, '30a010f3fd2da8f1_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08d46278-69cf-4f30-8a13-981dca286c96', 'b0000000-0000-0000-0000-000000000027', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'understand', 'What is the purpose of the Junos REST API?', '[{"id": "A", "text": "Allows HTTP-based access to Junos operational commands and configuration", "is_correct": true}, {"id": "B", "text": "Replaces NETCONF entirely", "is_correct": false}, {"id": "C", "text": "Provides a web UI for Junos", "is_correct": false}, {"id": "D", "text": "Manages only routing tables", "is_correct": false}]', 'Junos REST API provides HTTP-based access to execute operational commands, modify configuration, and retrieve information. Uses standard HTTP methods.', '{"https://www.juniper.net/documentation/us/en/software/junos/rest-api/"}', 'REST API', 14.0, '45375636ff50cbd4_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44b263b1-d84b-4666-ba01-7281cf2edb1a', 'b0000000-0000-0000-0000-000000000027', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'In Junos, which YANG model is used for configuration and operational state?', '[{"id": "A", "text": "JUNOS YANG (Juniper native YANG models)", "is_correct": false}, {"id": "B", "text": "OpenConfig YANG", "is_correct": false}, {"id": "C", "text": "IETF YANG models", "is_correct": false}, {"id": "D", "text": "All of the above are supported", "is_correct": true}]', 'Junos supports Juniper native YANG, OpenConfig YANG, and IETF YANG models. Support depends on the Junos version and platform.', '{"https://www.juniper.net/documentation/us/en/software/junos/yang/"}', 'YANG/NETCONF', 14.0, '82f8254bf158a241_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('715f5f58-5baf-4dab-acf9-cd5514d0d8da', 'b0000000-0000-0000-0000-000000000027', 'a0000000-0000-0000-0000-000000000005', 'multiple-choice', 3, 'understand', 'Which two automation protocols are supported natively in Junos? (Select TWO)', '[{"id": "A", "text": "NETCONF over SSH", "is_correct": true}, {"id": "B", "text": "RESTCONF over HTTP", "is_correct": false}, {"id": "C", "text": "SNMPv3", "is_correct": false}, {"id": "D", "text": "gRPC", "is_correct": true}]', 'Junos natively supports NETCONF over SSH (port 830) and gRPC (for JTI telemetry). RESTCONF is available on some platforms. SNMP is for monitoring, not automation.', '{"https://www.juniper.net/documentation/us/en/software/junos/automation/"}', 'Automation Protocols', 14.0, 'a580f443e99b8c34_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8727627-dc8c-4306-ba80-15e5e3626039', 'b0000000-0000-0000-0000-000000000027', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 2, 'understand', 'What is Jinja2 commonly used for in Junos automation?', '[{"id": "A", "text": "Template-based configuration generation for Junos devices", "is_correct": true}, {"id": "B", "text": "Executing CLI commands remotely", "is_correct": false}, {"id": "C", "text": "Collecting syslog data", "is_correct": false}, {"id": "D", "text": "Monitoring interface statistics", "is_correct": false}]', 'Jinja2 is a Python templating engine used with Ansible (junos_template) or Python (PyEZ) to generate Junos configuration from templates with variables.', '{"https://www.juniper.net/documentation/us/en/software/junos/automation/"}', 'Automation Tooling', 12.0, 'c6c59106fc5e96e3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16913bb4-ec5d-4b1c-bd98-69ab6ca9332b', 'b0000000-0000-0000-0000-000000000027', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 2, 'understand', 'In Junos automation, what does ''commit check'' verify?', '[{"id": "A", "text": "Validates the syntax and semantics of the candidate configuration before committing", "is_correct": true}, {"id": "B", "text": "Applies the configuration immediately", "is_correct": false}, {"id": "C", "text": "Rolls back to the previous configuration", "is_correct": false}, {"id": "D", "text": "Compares the candidate with the active configuration", "is_correct": false}]', '''commit check'' validates the candidate configuration without applying it. It verifies syntax, resource availability, and semantic consistency.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Management', 12.0, '6dc59de074b507b5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
