INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13a418da-7c00-42b0-beb0-73bc730ab04b', 'b0000000-0000-0000-0000-000000000027', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 2, 'understand', 'What is Jinja2 commonly used for in Junos automation (variant 4).', '[{"id": "A", "text": "Template-based configuration generation for Junos devices", "is_correct": true}, {"id": "B", "text": "Executing CLI commands remotely", "is_correct": false}, {"id": "C", "text": "Collecting syslog data", "is_correct": false}, {"id": "D", "text": "Monitoring interface statistics", "is_correct": false}]', 'Jinja2 is a Python templating engine used with Ansible (junos_template) or Python (PyEZ) to generate Junos configuration from templates with variables (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/automation/"}', 'Automation Tooling', 12.0, 'b28d29773c8b439b_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fc3aa6b-05f2-4297-992c-b961304af354', 'b0000000-0000-0000-0000-000000000027', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 2, 'understand', 'In Junos automation, what does ''commit check'' verify (variant 4).', '[{"id": "A", "text": "Validates the syntax and semantics of the candidate configuration before committing", "is_correct": true}, {"id": "B", "text": "Applies the configuration immediately", "is_correct": false}, {"id": "C", "text": "Rolls back to the previous configuration", "is_correct": false}, {"id": "D", "text": "Compares the candidate with the active configuration", "is_correct": false}]', '''commit check'' validates the candidate configuration without applying it. It verifies syntax, resource availability, and semantic consistency (Variant 4).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Management', 12.0, '751902248b16eacc_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13f2164f-6f0a-423c-b35a-c6a063e7fc49', 'b0000000-0000-0000-0000-000000000027', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'Which Ansible module is used to apply a Junos configuration from a file (variant 5).', '[{"id": "A", "text": "junos_config", "is_correct": true}, {"id": "B", "text": "junos_install_config", "is_correct": false}, {"id": "C", "text": "netconf_config", "is_correct": false}, {"id": "D", "text": "junos_template", "is_correct": false}]', 'The ''junos_config'' module manages Junos configuration by loading, merging, or replacing configuration from a file or inline (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/ansible/"}', 'Ansible Automation', 14.0, '7a8bafef5e4996c8_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0fb0da3-982c-4f83-80b8-a9611e46ba73', 'b0000000-0000-0000-0000-000000000027', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'understand', 'What is the purpose of the Junos REST API (variant 5).', '[{"id": "A", "text": "Allows HTTP-based access to Junos operational commands and configuration", "is_correct": true}, {"id": "B", "text": "Replaces NETCONF entirely", "is_correct": false}, {"id": "C", "text": "Provides a web UI for Junos", "is_correct": false}, {"id": "D", "text": "Manages only routing tables", "is_correct": false}]', 'Junos REST API provides HTTP-based access to execute operational commands, modify configuration, and retrieve information. Uses standard HTTP methods (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/rest-api/"}', 'REST API', 14.0, 'f9f97a2e15767a59_gen_v3', true) ON CONFLICT (id) DO NOTHING;
