INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ec39e59-d482-4957-9310-140738549aa3', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 5, 'apply', 'What is the recommended approach for implementing a CI/CD pipeline for Junos configuration changes?', '[{"id": "A", "text": "Validate configuration in a staging environment before production deployment", "is_correct": true}, {"id": "B", "text": "Directly push configuration to production", "is_correct": false}, {"id": "C", "text": "Use only manual CLI changes", "is_correct": false}, {"id": "D", "text": "Use only SNMP for configuration", "is_correct": false}]', 'Best practice: validate config in staging using tools like Ansible+PyEZ, run commit-check and commit-confirm, then promote to production.', '{"https://www.juniper.net/documentation/us/en/software/junos/automation/"}', 'Automation Pipelines', 16.0, '9bbd5e5f7a5dd358_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ded4c5ef-6ff3-4b33-8303-fb984e2b9ad9', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'In Junos telemetry (JTI), what is a ''sensor''?', '[{"id": "A", "text": "A configuration that defines which operational data to stream and how often", "is_correct": true}, {"id": "B", "text": "A physical temperature sensor on the device", "is_correct": false}, {"id": "C", "text": "A SNMP trap receiver", "is_correct": false}, {"id": "D", "text": "A syslog collector", "is_correct": false}]', 'A JTI sensor defines the data collection parameters: which operational data (e.g., interface statistics, routing table entries) to stream and the reporting interval.', '{"https://www.juniper.net/documentation/us/en/software/junos/telemetry/"}', 'Junos Telemetry', 14.0, '8f9e6097c17e9c50_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57d27633-0ba7-4b2e-a7e8-65e096bfbeb4', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which tool is commonly used with gRPC for Junos telemetry collection?', '[{"id": "A", "text": "JTI (Junos Telemetry Interface) collector", "is_correct": true}, {"id": "B", "text": "OpenConfig telemetry", "is_correct": false}, {"id": "C", "text": "SNMP MIB walker", "is_correct": false}, {"id": "D", "text": "Syslog-ng", "is_correct": false}]', 'JTI collector (or Junos Telemetry collector) receives streaming telemetry data via gRPC from Junos devices. OpenConfig also defines telemetry models.', '{"https://www.juniper.net/documentation/us/en/software/junos/telemetry/"}', 'Telemetry', 14.0, '9116c66dbb620099_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('756116e7-30cc-4d3a-a5d8-ee61777e708f', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which Junos automation feature enables event-driven responses to system events?', '[{"id": "A", "text": "Event scripts (commit/op scripts triggered by system events)", "is_correct": true}, {"id": "B", "text": "CRON scheduler", "is_correct": false}, {"id": "C", "text": "SNMP traps", "is_correct": false}, {"id": "D", "text": "Manual CLI monitoring", "is_correct": false}]', 'Junos event scripts are triggered by system events (interface down, BGP down, etc.) and can execute predefined automation actions to respond automatically.', '{"https://www.juniper.net/documentation/us/en/software/junos/automation-scripts/"}', 'Event Automation', 14.0, '5cb7d11c2fa126ef_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b34b73bb-7913-4d2a-9b50-34e3eca6450e', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 2, 'understand', 'What is the purpose of ''commit confirmed'' in Junos?', '[{"id": "A", "text": "Applies configuration temporarily; automatically rolls back if not confirmed within the timeout", "is_correct": true}, {"id": "B", "text": "Commits the configuration permanently", "is_correct": false}, {"id": "C", "text": "Displays the commit history", "is_correct": false}, {"id": "D", "text": "Checks configuration syntax only", "is_correct": false}]', '''commit confirmed <minutes>'' applies the candidate config for a test period. If not confirmed with another ''commit'' within the timeout, automatic rollback occurs.', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Management', 12.0, '37055b5fb6fa3bb9_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72a03df9-3879-40ea-9c30-c9029661f4a8', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 5, 'apply', 'What is the recommended approach for implementing a CI/CD pipeline for Junos configuration changes (variant 2).', '[{"id": "A", "text": "Validate configuration in a staging environment before production deployment", "is_correct": true}, {"id": "B", "text": "Directly push configuration to production", "is_correct": false}, {"id": "C", "text": "Use only manual CLI changes", "is_correct": false}, {"id": "D", "text": "Use only SNMP for configuration", "is_correct": false}]', 'Best practice: validate config in staging using tools like Ansible+PyEZ, run commit-check and commit-confirm, then promote to production (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/automation/"}', 'Automation Pipelines', 16.0, 'e29687b390d5df8f_gen_v3', true) ON CONFLICT (id) DO NOTHING;
