INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6f35a92-3bf1-415a-8c65-cf7a4377d7bb', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 2, 'understand', 'What is the purpose of ''commit confirmed'' in Junos (variant 5).', '[{"id": "A", "text": "Applies configuration temporarily; automatically rolls back if not confirmed within the timeout", "is_correct": true}, {"id": "B", "text": "Commits the configuration permanently", "is_correct": false}, {"id": "C", "text": "Displays the commit history", "is_correct": false}, {"id": "D", "text": "Checks configuration syntax only", "is_correct": false}]', '''commit confirmed <minutes>'' applies the candidate config for a test period. If not confirmed with another ''commit'' within the timeout, automatic rollback occurs (Variant 5).', '{"https://www.juniper.net/documentation/us/en/software/junos/cli/"}', 'Configuration Management', 12.0, 'e6094c82ee361797_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a8b0d55-2bd7-47d5-9473-71658e411654', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 5, 'apply', 'What is the recommended approach for implementing a CI/CD pipeline for Junos configuration changes (variant 6).', '[{"id": "A", "text": "Validate configuration in a staging environment before production deployment", "is_correct": true}, {"id": "B", "text": "Directly push configuration to production", "is_correct": false}, {"id": "C", "text": "Use only manual CLI changes", "is_correct": false}, {"id": "D", "text": "Use only SNMP for configuration", "is_correct": false}]', 'Best practice: validate config in staging using tools like Ansible+PyEZ, run commit-check and commit-confirm, then promote to production (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/automation/"}', 'Automation Pipelines', 16.0, '4f2c29d678d2867c_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad573432-2b02-4a2e-b5c5-fb7cdeb875ab', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'In Junos telemetry (JTI), what is a ''sensor'' (variant 6).', '[{"id": "A", "text": "A configuration that defines which operational data to stream and how often", "is_correct": true}, {"id": "B", "text": "A physical temperature sensor on the device", "is_correct": false}, {"id": "C", "text": "A SNMP trap receiver", "is_correct": false}, {"id": "D", "text": "A syslog collector", "is_correct": false}]', 'A JTI sensor defines the data collection parameters: which operational data (e.g., interface statistics, routing table entries) to stream and the reporting interval (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/telemetry/"}', 'Junos Telemetry', 14.0, '447074f4d0a1c1a6_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d8ae6349-b32e-46ca-b102-8d86cacfdf62', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'Which tool is commonly used with gRPC for Junos telemetry collection (variant 6).', '[{"id": "A", "text": "JTI (Junos Telemetry Interface) collector", "is_correct": true}, {"id": "B", "text": "OpenConfig telemetry", "is_correct": false}, {"id": "C", "text": "SNMP MIB walker", "is_correct": false}, {"id": "D", "text": "Syslog-ng", "is_correct": false}]', 'JTI collector (or Junos Telemetry collector) receives streaming telemetry data via gRPC from Junos devices. OpenConfig also defines telemetry models (Variant 6).', '{"https://www.juniper.net/documentation/us/en/software/junos/telemetry/"}', 'Telemetry', 14.0, 'b1ade60597aa32f3_gen_v3', true) ON CONFLICT (id) DO NOTHING;
