INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c251ab9-72c5-48b9-8759-c3f92480034a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which IPv6 address type is equivalent to a private IPv4 address?', '[{"id": "A", "text": "Unique Local (fc00::/7)", "is_correct": true}, {"id": "B", "text": "Link-Local (fe80::/10)", "is_correct": false}, {"id": "C", "text": "Global Unicast (2000::/3)", "is_correct": false}, {"id": "D", "text": "Multicast (ff00::/8)", "is_correct": false}]', 'Unique Local Unicast addresses (fc00::/7) are the IPv6 equivalent of RFC 1918 private addresses. They are not globally routable.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IPv6', 12.0, 'e164be35a68099ad_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dfb9d9b5-3881-41c7-b1c0-57519fac17cb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the ''spanning-tree portfast'' command on a Cisco switch?', '[{"id": "A", "text": "Bypasses the listening and learning states for access ports", "is_correct": true}, {"id": "B", "text": "Enables rapid STP on the port", "is_correct": false}, {"id": "C", "text": "Disables STP on the port", "is_correct": false}, {"id": "D", "text": "Configures the port as a trunk", "is_correct": false}]', 'PortFast immediately transitions a port from blocking to forwarding state, bypassing listening and learning. Used only on access ports connected to end hosts.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'STP', 12.0, '3870024e57ceadba_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5073db4-4461-43b1-85ee-c323a67875ad', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is considered link-state?', '[{"id": "A", "text": "OSPF", "is_correct": true}, {"id": "B", "text": "RIP", "is_correct": false}, {"id": "C", "text": "EIGRP", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'OSPF (Open Shortest Path First) is a link-state routing protocol. It maintains a complete view of the network topology using LSAs.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'Routing Protocols', 12.0, '324845a958553513_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f124f4b-a96b-4516-9cf2-eaf6d29eb820', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the administrative distance of External EIGRP?', '[{"id": "A", "text": "170", "is_correct": true}, {"id": "B", "text": "20", "is_correct": false}, {"id": "C", "text": "90", "is_correct": false}, {"id": "D", "text": "110", "is_correct": false}]', 'External EIGRP routes (redistributed) have AD 170. Internal EIGRP has AD 90.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'Routing Fundamentals', 12.0, 'f15ff47637247091_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c6fea15-9f36-4029-87b3-70da294f2670', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which Cisco protocol provides first-hop redundancy?', '[{"id": "A", "text": "HSRP", "is_correct": true}, {"id": "B", "text": "STP", "is_correct": false}, {"id": "C", "text": "CDP", "is_correct": false}, {"id": "D", "text": "LLDP", "is_correct": false}]', 'HSRP (Hot Standby Router Protocol) is Cisco''s FHRP that provides default gateway redundancy by allowing two or more routers to share a virtual IP and MAC address.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipapp_fhrp/"}', 'First Hop Redundancy', 12.0, '070955320def8d81_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14a8c77b-c16a-4d14-8dfb-2f8c888400b7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'What does VLAN 1 represent on a Cisco switch by default?', '[{"id": "A", "text": "The default management VLAN - all ports belong to VLAN 1", "is_correct": true}, {"id": "B", "text": "A reserved VLAN for voice traffic", "is_correct": false}, {"id": "C", "text": "A native VLAN for trunk ports only", "is_correct": false}, {"id": "D", "text": "An unused VLAN for security isolation", "is_correct": false}]', 'By default, all switch ports are in VLAN 1, which also carries management traffic including CDP, VTP, PAgP, and DTP.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'VLAN', 12.0, '43e88ded1e339ab5_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4df65592-8283-4406-b151-dbdf11ca3087', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of DTP (Dynamic Trunking Protocol) on Cisco switches?', '[{"id": "A", "text": "Automatically negotiates trunking mode between connected switches", "is_correct": true}, {"id": "B", "text": "Dynamically assigns VLANs to access ports", "is_correct": false}, {"id": "C", "text": "Detects topology changes in the network", "is_correct": false}, {"id": "D", "text": "Provides authentication between switches", "is_correct": false}]', 'DTP is a Cisco proprietary protocol that negotiates the trunking mode (access/trunk/dynamic) between two connected switch interfaces.', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Trunking', 12.0, '406dbf364c6bb908_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5c99504-6ebd-4737-be95-8dd9e24afe36', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which IPv6 address type is equivalent to a private IPv4 address (variant 2).', '[{"id": "A", "text": "Unique Local (fc00::/7)", "is_correct": true}, {"id": "B", "text": "Link-Local (fe80::/10)", "is_correct": false}, {"id": "C", "text": "Global Unicast (2000::/3)", "is_correct": false}, {"id": "D", "text": "Multicast (ff00::/8)", "is_correct": false}]', 'Unique Local Unicast addresses (fc00::/7) are the IPv6 equivalent of RFC 1918 private addresses. They are not globally routable (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IPv6', 12.0, 'ac81ba428af5630e_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a87ff42-137e-4618-b68f-5522869027d3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the ''spanning-tree portfast'' command on a Cisco switch (variant 2).', '[{"id": "A", "text": "Bypasses the listening and learning states for access ports", "is_correct": true}, {"id": "B", "text": "Enables rapid STP on the port", "is_correct": false}, {"id": "C", "text": "Disables STP on the port", "is_correct": false}, {"id": "D", "text": "Configures the port as a trunk", "is_correct": false}]', 'PortFast immediately transitions a port from blocking to forwarding state, bypassing listening and learning. Used only on access ports connected to end hosts (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'STP', 12.0, '9c22022f2f7f7dee_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('270ce9ed-cdf6-4271-bc85-a571cf0c965e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is considered link-state (variant 2).', '[{"id": "A", "text": "OSPF", "is_correct": true}, {"id": "B", "text": "RIP", "is_correct": false}, {"id": "C", "text": "EIGRP", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'OSPF (Open Shortest Path First) is a link-state routing protocol. It maintains a complete view of the network topology using LSAs (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'Routing Protocols', 12.0, 'c57118992f9ccedb_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1896898-bfde-4d87-8d62-3b669f4ef4c7', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'remember', 'What is the administrative distance of External EIGRP (variant 2).', '[{"id": "A", "text": "170", "is_correct": true}, {"id": "B", "text": "20", "is_correct": false}, {"id": "C", "text": "90", "is_correct": false}, {"id": "D", "text": "110", "is_correct": false}]', 'External EIGRP routes (redistributed) have AD 170. Internal EIGRP has AD 90 (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/iproute/"}', 'Routing Fundamentals', 12.0, '1024150c6f2ccf59_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed43b054-9771-4f21-ba7e-ad1484249369', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which Cisco protocol provides first-hop redundancy (variant 2).', '[{"id": "A", "text": "HSRP", "is_correct": true}, {"id": "B", "text": "STP", "is_correct": false}, {"id": "C", "text": "CDP", "is_correct": false}, {"id": "D", "text": "LLDP", "is_correct": false}]', 'HSRP (Hot Standby Router Protocol) is Cisco''s FHRP that provides default gateway redundancy by allowing two or more routers to share a virtual IP and MAC address (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipapp_fhrp/"}', 'First Hop Redundancy', 12.0, '82f712596fb7cce7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
